const defaultProducts=()=>Object.fromEntries(productSpecs.map(p=>[p.id,{price:p.default,enabled:true}]));
const getPrice=(s,id)=>Number(s.products?.[id]?.price??productSpecs.find(p=>p.id===id)?.default??0);
