const deposits=s=>s.clients.reduce((n,c)=>n+c.balance,0);const credit=s=>s.loans.reduce((n,l)=>n+l.balance,0);const securities=s=>Object.entries(s.shares).reduce((n,[id,q])=>n+q*(s.marketPrices[id]||0),0);const assets=s=>s.cash+credit(s)+securities(s);const liabilities=s=>deposits(s)+s.externalFunding;const equity=s=>assets(s)-liabilities(s);const payroll=s=>s.staff.reduce((n,e)=>n+e.salary,0);const branchCost=s=>s.branches.reduce((n,b)=>n+b.rent,0);const rwa=s=>credit(s)*.75+securities(s)*.50;const ratio=s=>rwa(s)<1000?null:100*equity(s)/rwa(s);const pnb=s=>s.totals.interest+s.totals.fees-s.totals.interestExpense+s.totals.market;const result=s=>pnb(s)-s.totals.salaries-s.totals.rent-s.totals.creditLoss;const staffCount=(group,branch)=>state.staff.filter(x=>x.group===group&&(branch==null||x.branch===branch)).length;
function log(s,msg){s.logs.unshift({id:++s.counter,date:s.date,msg});s.logs=s.logs.slice(0,300)}
function save(){try{localStorage.setItem(KEY,JSON.stringify({...state,running:false}));return true}catch(e){notify('Échec de sauvegarde locale : '+e.message);return false}}
function notify(t){document.querySelector('.toast')?.remove();let d=document.createElement('div');d.className='toast';d.textContent=t;document.body.append(d);clearTimeout(toastTimer);toastTimer=setTimeout(()=>d.remove(),3800)}
