    const seller=pick(s,sellers),pool=s.clients.filter(c=>c.branch===seller.branch);
    if(!pool.length)continue;
    const c=pick(s,pool),principal=Math.round((c.kind==='Entreprise'?140000:c.kind==='Professionnel'?52000:23000)*(.65+rand(s)*1.6)/1000)*1000;
    const duration=c.kind==='Particulier'?pick(s,[48,84,180,240]):pick(s,[24,48,72,120]);
    const score=Math.round(35+rand(s)*62),income=Math.round((c.kind==='Entreprise'?28000:c.kind==='Professionnel'?7500:2900)*(.75+rand(s)*.9));
    s.applications.push({id:++s.counter,client:c.id,advisor:seller.id,amount:principal,rate:round(Math.max(1,Math.min(20,(c.kind==='Particulier'&&duration>=180?getPrice(s,'mortgage'):c.kind==='Particulier'?getPrice(s,'consumer'):getPrice(s,'businessLoan'))+(.5-rand(s))*.5))),duration,score,income,status:'À décider',created:s.date,history:[]});
